"""Writes the TextMate grammar of the Visual Studio Code extension (tools/vscode/syntaxes/blitzbasic.tmLanguage.json).

The names of the commands come from tests/suite/functions.txt, the list that the wiki and the language server use as well, so
that a new command is highlighted by running this script again:  python3 tools/generate_vscode_grammar.py [--output file]
The file is not kept in the repository, the build of the extension writes it.
"""
import json
import os
import sys

ROOT = os.path.normpath(os.path.join(os.path.dirname(os.path.abspath(__file__)), ".."))
LIST = os.path.join(ROOT, "tests", "suite", "functions.txt")
OUT = os.path.join(ROOT, "tools", "vscode", "syntaxes", "blitzbasic.tmLanguage.json")

CONTROL = ["If", "Then", "Else", "ElseIf", "EndIf", "End If", "While", "Wend", "For", "To", "Step", "Next", "Repeat", "Until", "Forever",
           "Select", "Case", "Default", "End Select", "EndSelect", "Exit", "Return", "Goto", "Gosub", "End", "Stop", "Include", "Data", "Read", "Restore"]
DECLARATION = ["Function", "End Function", "EndFunction", "Type", "End Type", "EndType", "Dim", "Const", "Global", "Local", "Field"]
OBJECT = ["New", "Delete", "Each", "First", "Last", "Insert", "Before", "After"]
OPERATOR = ["And", "Or", "Not", "Xor", "Mod", "Shl", "Shr", "Sar"]
CONSTANT = ["True", "False", "Null", "Pi"]
TYPES = ["Int", "Int8", "Int16", "Int32", "Int64", "UInt", "UInt8", "UInt16", "UInt32", "UInt64", "Byte", "Short", "Long", "ULong", "Float",
         "Float32", "Float64", "Real", "Real32", "Real64", "Double", "String", "Void"]


def words(names):
    """A pattern for the keywords; the ones with a space allow any white space between the words."""
    return r"\b(?:" + "|".join(n.replace(" ", r"[ \t]+") for n in sorted(names, key=lambda x: (-len(x), x))) + r")\b"


def commands():
    names = set()
    for line in open(LIST, encoding="utf-8"):
        if line.startswith("#") or not line.strip():
            continue
        columns = line.rstrip("\n").split("\t")
        if len(columns) < 4:
            continue
        signature = columns[3].lstrip("%#$!~")
        name = ""
        for c in signature:
            if c.isalnum() or c == "_":
                name += c
            else:
                break
        if name:
            names.add(name)
    return sorted(names, key=str.lower)


def grammar():
    name = r"[A-Za-z_][A-Za-z0-9_]*"
    return {
        "$schema": "https://raw.githubusercontent.com/martinring/tmlanguage/master/tmlanguage.json",
        "name": "BlitzBasic",
        "scopeName": "source.blitzbasic",
        "patterns": [{"include": "#comment"}, {"include": "#string"}, {"include": "#label"}, {"include": "#declaration"}, {"include": "#variable_list"}, {"include": "#type_ref"}, {"include": "#number"},
                     {"include": "#typename"}, {"include": "#field"}, {"include": "#keyword"}, {"include": "#builtin"}, {"include": "#operator"},
                     {"include": "#sigil_variable"}, {"include": "#suffix"}],
        "repository": {
            "comment": {"name": "comment.line.semicolon.blitzbasic", "match": ";.*$"},
            "string": {"name": "string.quoted.double.blitzbasic", "begin": "\"", "end": "(\"|$)"},
            "label": {"match": r"^\s*(\.)(" + name + ")", "captures": {"1": {"name": "punctuation.definition.label.blitzbasic"}, "2": {"name": "entity.name.label.blitzbasic"}}},
            "declaration": {"patterns": [
                {"match": r"(?i)\b(Function)[ \t]+(" + name + ")", "captures": {"1": {"name": "keyword.declaration.function.blitzbasic"}, "2": {"name": "entity.name.function.blitzbasic"}}},
                {"match": r"(?i)\b(Type)[ \t]+(" + name + ")", "captures": {"1": {"name": "keyword.declaration.type.blitzbasic"}, "2": {"name": "entity.name.type.blitzbasic"}}},
                {"match": r"(?i)\b(Field)[ \t]+(" + name + ")", "captures": {"1": {"name": "keyword.declaration.field.blitzbasic"}, "2": {"name": "variable.other.member.blitzbasic"}}},
                {"match": r"(?i)\b(Const)[ \t]+(" + name + ")", "captures": {"1": {"name": "keyword.declaration.const.blitzbasic"}, "2": {"name": "variable.other.constant.blitzbasic"}}},
            ]},
            "number": {"patterns": [
                {"name": "constant.numeric.hex.blitzbasic", "match": r"(?i)(\$|\b0x)[0-9a-f]+\b"},
                {"name": "constant.numeric.binary.blitzbasic", "match": r"(\%|\b0b)[01]+\b"},
                {"name": "constant.numeric.float.blitzbasic", "match": r"(\b\d+\.\d*|\.\d+)([eE][+-]?\d+)?"},
                {"name": "constant.numeric.integer.blitzbasic", "match": r"\b\d+\b"},
            ]},
            "typename": {"match": r"(?i)(?<=[A-Za-z0-9_%#$\)])(:)(" + "|".join(TYPES) + r"|" + name + r")\b", "captures": {"1": {"name": "punctuation.separator.type.blitzbasic"}, "2": {"name": "storage.type.blitzbasic"}}},
            "field": {"match": r"(\\)[ \t]*(" + name + ")", "captures": {"1": {"name": "punctuation.accessor.blitzbasic"}, "2": {"name": "variable.other.member.blitzbasic"}}},
            "keyword": {"patterns": [
                {"name": "keyword.declaration.blitzbasic", "match": "(?i)" + words(DECLARATION)},
                {"name": "keyword.control.blitzbasic", "match": "(?i)" + words(CONTROL)},
                {"name": "keyword.other.object.blitzbasic", "match": "(?i)" + words(OBJECT)},
                {"name": "keyword.operator.expression.blitzbasic keyword.operator.wordlike.blitzbasic", "match": "(?i)" + words(OPERATOR)},
                {"name": "constant.language.blitzbasic", "match": "(?i)" + words(CONSTANT)},
            ]},
            # `x.Type` and `New Type`, `Each Type`, `First Type`, `Last Type`
            "type_ref": {"patterns": [
                {"match": r"(?<=[A-Za-z0-9_%#$\)])(\.)(" + name + ")", "captures": {"1": {"name": "punctuation.separator.type.blitzbasic"}, "2": {"name": "storage.type.blitzbasic"}}},
                {"match": r"(?i)\b(New|Each|First|Last)[ \t]+(" + name + ")", "captures": {"1": {"name": "keyword.other.object.blitzbasic"}, "2": {"name": "storage.type.blitzbasic"}}},
            ]},
            # Everything in a Local, Global or Dim statement that is not a keyword, a command or a type is a variable.
            "variable_list": {"begin": r"(?i)\b(Local|Global|Dim)\b", "beginCaptures": {"1": {"name": "keyword.declaration.variable.blitzbasic"}}, "end": r"(?=;)|$", "patterns": [
                {"include": "#string"}, {"include": "#number"}, {"include": "#type_ref"}, {"include": "#typename"}, {"include": "#field"}, {"include": "#keyword"}, {"include": "#builtin"},
                {"include": "#operator"}, {"include": "#suffix"},
                {"match": r"(?<![\\.\w])" + name, "name": "variable.other.readwrite.blitzbasic"},
            ]},
            # A name with a type character is a variable, wherever it is (the others need the language server, which knows the declarations).
            "sigil_variable": {"match": r"\b(" + name + r")(?=[%#$])", "name": "variable.other.readwrite.blitzbasic"},
            "builtin": {"name": "support.function.builtin.blitzbasic", "match": "(?i)" + words(commands())},
            "operator": {"name": "keyword.operator.blitzbasic", "match": r"<>|<=|>=|[-+*/^=<>~]"},
            "suffix": {"name": "storage.type.suffix.blitzbasic", "match": r"(?<=[A-Za-z0-9_\)])(##|%%|[%#$])"},
        },
    }


def main():
    # The grammar is generated from the commands of the runtime, so it is not kept in the repository: the build of the extension and
    # whoever runs the extension from the sources generate it. --output writes it somewhere else (the test does that).
    out = OUT
    if "--output" in sys.argv:
        out = sys.argv[sys.argv.index("--output") + 1]
    text = json.dumps(grammar(), indent="\t", ensure_ascii=False) + "\n"
    os.makedirs(os.path.dirname(os.path.abspath(out)), exist_ok=True)
    with open(out, "w", encoding="utf-8", newline="\n") as f:
        f.write(text)
    return 0


if __name__ == "__main__":
    sys.exit(main())
